-- GENERATED by `wfj generate` from data/gossip/gossip-86.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["8601f6c2a68134ce"] = { "Preparatevi! Evocare un essere così potente porta di rado a buoni risultati.", "." },
  ["860686181a0757d0"] = { "Distruzione di %s. Assalto aereo impossibilitato a confermare il punto d'impatto. Missione annullata.", "." },
  ["860abe61dafa378f"] = { "Hai visto tutte le cose meravigliose che ci sono qui nel Cratere di Un'Goro, {name}? È semplicemente stupendo. Non stupendo come certe cose che so costruire con la mia abilità d'ingegneria, ma per essere tutto naturale... non è niente male.\n\nMio zio Remtravel adora le cose antiche come questo posto. Sto un po' seguendo le sue orme: anch'io voglio scoprire cose nuove dalle culture perdute!", "." },
  ["860b4cb24dd5fc81"] = { "Una tale saggezza è avvolta in un mistero che si può trovare solo nel grande ⟦Thunder Bluff=Picco del Tuono⟧. Segui il sentiero a nord fuori dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ finché non arrivi a un ascensore ai piedi delle alture. Prendilo fino in cima e chiedi ulteriore aiuto a uno dei Guardiani del Picco.", "." },
  ["860d1e3237479672"] = { "Sì, lo faremo!", "." },
  ["86123b41d54774be"] = { "In quanto <mago/maga>, fai parte di una cerchia ristretta capace di evocare un portale che ti riporti proprio qui. Posso insegnartelo, se te la senti.", "." },
  ["8613cc7e71a0ba31"] = { "<Benvenuto/Benvenuta>, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, sarò felice di farlo.\n\nSiamo i custodi dell'equilibrio, ora e per sempre, come ci ha insegnato Cenarius. Non dimenticarlo mai.", "." },
  ["8617a389bd176719"] = { "Notevole, {class}. Nessuno dubiterà più dei miei racconti quando tornerò a Orgrimmar con questa macabra prova dell'esistenza di questi abomini. Ma sappi che questa gloria è tua, e parlerò a gran voce delle tue imprese.\n\nLok-tar!", "." },
  ["861b5979eb43b748"] = { "Non si vedono molti fabbri così lontano da ⟦Ironforge=Forgiardente⟧. Cosa posso fare per te?", "." },
  ["861c4c41d2641eca"] = { "%s ha l'aria stanca. Poi sbadiglia e si sdraia accanto ad ⟦A-Me 01=E-Mi 01⟧", "." },
  ["86222efd23b1bb0f"] = { "E di onore ne avrai molto, non ho dubbi. Parla con Martin Lindsey alle Pozze delle Visioni. È una grotta sul fianco dell'⟦Spirit Rise=Altura degli Spiriti⟧.", "." },
  ["862f76834e644458"] = { "La ⟦Might of Kalimdor=Forza di Kalimdor⟧ fermerà la loro avanzata!", "." },
  ["8631479d57a91197"] = { "Confido che la Luce sia con te, {name}. C'è qualcosa in cui posso aiutarti?", "." },
  ["86358ad34cb9fff6"] = { "Hai fatto bene a cercarmi. Ti chiederei un piccolo favore. In cambio, posso insegnarti molto.", "." },
  ["863cc235a53b93ad"] = { "Preda misera.", "." },
  ["8641c68b029aae7d"] = { "Brzzzzt!\n\n<Benvenuto/Benvenuta> al Matrix Punchograph 3005 barra A, un terminale di livello di sicurezza alfa.\n\nPer accedere alle funzioni del terminale devi possedere una scheda perforata bianca.\n\n01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001", "." },
  ["86463319cbb3367d"] = { "Le nostre unità campione stanno lasciando il campo. Ci servono altri rifornimenti!", "." },
  ["8651a47757186178"] = { "<Copia lo schema nel tuo quaderno di ingegneria.>", "." },
  ["86533a1b31ea249f"] = { "L'abominio ha travolto il campo dei Guardiani della Notte! Presto, dobbiamo intercettarlo prima che raggiunga il paese!", "." },
  ["86647f4dbae8d1ce"] = { "Dimostra il tuo apprezzamento per l'arte e lascia cadere qualche moneta nel mio cappello!", "." },
  ["8664db2ac2f53bf8"] = { "Ora c'è solo una via d'uscita: percorrere il sentiero solitario dei dannati.", "." },
  ["866c6d50320d030a"] = { "Che il destino sia così crudele da concederci solo questo dopo mille anni di lontananza...", "." },
  ["866f1cbb6deb54c4"] = { "Ehi, tu! Se vuoi guadagnarti il rispetto dei nani di ⟦Ironforge=Forgiardente⟧, puoi cominciare donando risorse preziose! ⟦Ironforge=Forgiardente⟧ è a corto di stoffa; tessuti e bende non crescono sugli alberi, sai!\n\nInvece di monetizzare le varie stoffe che trovi durante le tue avventure, donale! Così ti guadagnerai la riconoscenza del popolo nanico di ⟦Ironforge=Forgiardente⟧!", "." },
  ["867d1292537553db"] = { "Dov'è l'anziano Winterhoof?", "." },
  ["86870c6a354256bd"] = { "Certo che posso insegnarti la nobile arte di maneggiare un'arma ad asta, ma ti costerà.", "." },
  ["868a1c2b7b0f17ad"] = { "La risposta non si vede attraverso la Distorsione Fatua.", "." },
  ["868dbf08fbed3327"] = { "Ecco la ⟦Cathedral of Light=Cattedrale della Luce⟧, il centro dell'illuminazione spirituale qui a ⟦Stormwind=Roccavento⟧.", "." },
  ["869caec3f8e66924"] = { "Grazie, signora Chambers.", "." },
  ["86a2dc958bbc2f1f"] = { "Maestro delle viverne", "." },
  ["86a6c511e21bdb47"] = { "Mi hai dato un aiuto incredibile! Queste ossa sveleranno tantissime nuove informazioni e mi aiuteranno a portare avanti le mie ricerche.", "." },
  ["86add64096897e61"] = { "<Stolto/Stolta> {class}! Spezzerò le ossa di questo debole {race}!", "." },
  ["86af9fc72bc05640"] = { "Ah, sei tu ad aver trovato la lettera. Grazie per la... notizia, credo, sulla mia ex famiglia. Prendi pure il cibo e le bevande che posso offrirti.", "." },
  ["86b2d2e7103c2498"] = { "Vuoi un'arma che sia un'estensione del tuo stesso pugno? Sì, credo di poterti mostrare qualcosa.", "." },
  ["86b3808535967e13"] = { "Mostrami cosa hai in vendita.", "." },
  ["86b3a1541f0f3ba2"] = { "Ti prego, insegnami a diventare fabbro d'asce, Kilram.", "." },
  ["86bb0ff8b9d44cde"] = { "Informazioni sulla ⟦Skin of Shadow=Pelle dell'Ombra⟧.", "." },
  ["86cffc905db5c5f2"] = { "Successo, il varco è aperto!! Fratelli miei, sorgete e tornate a casa! Le ⟦Outland=Terre Esterne⟧ vi attendono!", "." },
  ["86d85dc1b9515aed"] = { "Gli umani avevano costruito una locanda ai margini delle ⟦Barrens=Savane⟧. La chiamavano Ombracalma. Settimane fa è stata bruciata.\n\nIl Capoguerra ci ha detto di lasciare in pace gli umani, purché non attraversassero i nostri confini, ma pare che qualcuno abbia violato la sua volontà.\n\nMi ha incaricato di andare a fondo della faccenda. Se vuoi dare una mano, va' ai resti della ⟦Shady Rest Inn=Locanda Ombracalma⟧ e riportami tutti gli indizi che trovi.", "." },
  ["86ddc0de0b2fc17d"] = { "«Diario mistico di Khadgar, volume 8». Credo sia quello che volevo.", "." },
  ["86e64235ce658693"] = { "Quante battaglie abbiamo vinto?", "." },
  ["86ed00bdf1ecc310"] = { "%s si libera dai suoi vincoli spettrali con un tremendo fragore di tuono!", "." },
  ["86edfa122ce58899"] = { "Nelle acque della parte settentrionale della ⟦Sar'theris Strand=Riva di Sar'theris⟧, a ⟦Desolace=Desolanda⟧, o nella ⟦Angor Fortress=Fortezza di Angor⟧, nelle ⟦Badlands=Maleterre⟧, ci sono casse chiuse a chiave che si possono scassinare.", "." },
  ["86f9d0d9ce05da29"] = { "Là fuori è un disastro, {name}! Hai raccolto i pezzi che mi servono?", "." },
  ["86fa5bbc752ebb66"] = { "Salute, {name}. Non torneresti da me se non avessi portato a termine il tuo compito. Lascia che sia la prima a darti il benvenuto, a pieno titolo, sul primo dei quattro sentieri che governeranno per sempre i tuoi viaggi.\n\nSe hai la pietra che la terra ti ha dato, ti darò il totem che ti ha promesso. Altrimenti, provo pena per te. C'è molto di cui andare fieri quando ci si è dedicati completamente agli elementi.", "." },
})
